"""Pinned, transactional CT109 recovery installer. No real audit or publication."""
import base64
import fcntl
import hashlib
import os
from pathlib import Path
import socket
import subprocess
import tempfile
import time

MANIFEST = {'automation/server/runner.py': {'data': '', 'sha256': '2b12667784a8cb50d833a63690e9bb5c01cc4c77045769be38744ed1eedf7c3d', 'previous': ['1978740329e5722c473fd315df2a2304fa2f93f593fd2fa7236a286b484cf11f', 'f6aff75366869bb41d47ea8afb5ab9993cff7720e763dea15fe9c71578b22875'], 'systemd': False}, 'automation/server/recovery.py': {'data': '', 'sha256': '1d2802e56eea040323776187cb74858a4351bf6220c678bb1ff4d4849ff61ded', 'previous': [], 'systemd': False}, 'automation/server/phone_ui.py': {'data': '', 'sha256': '09282c1ec0bc343197aac2e3f3af553c49bcdb4678f02c80a4cf074f5b4f0cbf', 'previous': ['2b0a0f2d3aeaeef835ff4fb14e20ec1029a21fc1fc0d613cc17ba8cde223eba7'], 'systemd': False}, 'automation/server/diagnose.py': {'data': '', 'sha256': 'f053f857af4b4d4b04fc36a90c7ab6cff52228c864452c738beb63379fb4592d', 'previous': [], 'systemd': False}, 'automation/server/test_recovery.py': {'data': '', 'sha256': '3a938ccf8b65e2950b64f989047108fffe3f47e0ab2d1eb30aa746696d08c9f7', 'previous': [], 'systemd': False}, 'automation/server/test_diagnose.py': {'data': '', 'sha256': '152f5bb181e9baed63ede62970d88ea44b42562b4760b6f69f6544d7becf3e4b', 'previous': [], 'systemd': False}, 'automation/server/test_install_recovery.py': {'data': '', 'sha256': 'b366633b1a9581645817d1544f28b6c524e73ae6be1033a41d844ce4a73cea8d', 'previous': [], 'systemd': False}, 'automation/server/install.sh': {'data': '', 'sha256': 'bf5c387e88ffd772231c6f367e32eecf1d3fd56033d0b6f7065c4027f57f83ab', 'previous': ['e61f5121bc7dbe079a5c586826b1c4e20821bc92d15389880c0477f31ffc2241'], 'systemd': False}, 'automation/server/cutover.sh': {'data': '', 'sha256': 'a8b1a1bc49284b97a649983afefa606098c051d44755e72fd5e764fa6fd5c9a9', 'previous': ['9c56ee88479ba9f13b3943edd6944b6a11f1a952f6e27ce8e01d6c42d87ab611'], 'systemd': False}, 'automation/server/fh6-recovery.service': {'data': '', 'sha256': '4d5ae521dd9c33bb0bf390f266bfce282138b04939ad0c1ec876d2997d299e90', 'previous': [], 'systemd': False}, 'units/fh6-recovery.service': {'data': '', 'sha256': '4d5ae521dd9c33bb0bf390f266bfce282138b04939ad0c1ec876d2997d299e90', 'previous': [], 'systemd': True}, 'automation/server/fh6-recovery-run.service': {'data': '', 'sha256': '37afd7fde70fffea7450c7a3965ef9aa58b3bfb6e4f699f16b639105cdbc71ff', 'previous': [], 'systemd': False}, 'units/fh6-recovery-run.service': {'data': '', 'sha256': '37afd7fde70fffea7450c7a3965ef9aa58b3bfb6e4f699f16b639105cdbc71ff', 'previous': [], 'systemd': True}, 'automation/server/fh6-recovery.timer': {'data': 'W1VuaXRdCkRlc2NyaXB0aW9uPUNoZWNrIEZINiByZWNvdmVyeSBldmVyeSBmaXZlIG1pbnV0ZXMKW1RpbWVyXQpPbkJvb3RTZWM9Mm1pbgpPbkNhbGVuZGFyPSotKi0qICo6MC81OjAwCkFjY3VyYWN5U2VjPTE1cwpQZXJzaXN0ZW50PXRydWUKW0luc3RhbGxdCldhbnRlZEJ5PXRpbWVycy50YXJnZXQK', 'sha256': '93e09ae8d2273f1e8ec76c4416164129a879843502cad6b3dd6fe02d2e94529a', 'previous': [], 'systemd': False}, 'units/fh6-recovery.timer': {'data': 'W1VuaXRdCkRlc2NyaXB0aW9uPUNoZWNrIEZINiByZWNvdmVyeSBldmVyeSBmaXZlIG1pbnV0ZXMKW1RpbWVyXQpPbkJvb3RTZWM9Mm1pbgpPbkNhbGVuZGFyPSotKi0qICo6MC81OjAwCkFjY3VyYWN5U2VjPTE1cwpQZXJzaXN0ZW50PXRydWUKW0luc3RhbGxdCldhbnRlZEJ5PXRpbWVycy50YXJnZXQK', 'sha256': '93e09ae8d2273f1e8ec76c4416164129a879843502cad6b3dd6fe02d2e94529a', 'previous': [], 'systemd': True}}

def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def prepare(root,systemd,manifest=MANIFEST):
    plans=[]
    for name,item in manifest.items():
        raw=base64.b64decode(item['data'],validate=True)
        if digest(raw)!=item['sha256']:raise RuntimeError('Installer content mismatch: '+name)
        if name.endswith('.py'):compile(raw,name,'exec')
        target=(systemd/Path(name).name) if item['systemd'] else (root/name)
        if target.is_symlink():raise RuntimeError('Unexpected symlink: '+name)
        before=target.read_bytes() if target.exists() else None
        if before is not None and digest(before) not in item['previous']+[item['sha256']]:
            raise RuntimeError('Unknown installed version; no files changed: '+name)
        plans.append((target,raw,before,target.stat() if target.exists() else None))
    return plans

def replace(target,raw,uid,gid,mode):
    target.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.fh6-update-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.fchown(stream.fileno(),uid,gid);os.fchmod(stream.fileno(),mode)
        os.replace(temp,target)
    finally:
        if Path(temp).exists():Path(temp).unlink()

def main():
    if os.geteuid()!=0 or socket.gethostname()!='fh6-collector':
        raise RuntimeError('Run only as root inside CT109 fh6-collector')
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');systemd=Path('/etc/systemd/system')
    with (store/'runner.lock').open('a+b') as runner_lock,(root/'automation/runs/refresh/process.lock').open('a+b') as guard_lock:
        for lock in [runner_lock,guard_lock]:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        for unit in ['fh6-refresh.service','fh6-manual.service','fh6-recovery-run.service']:
            if unit=='fh6-recovery-run.service' and not (systemd/unit).exists():continue
            status=subprocess.run(['systemctl','show',unit,'--property=ActiveState','--value'],
                                  capture_output=True,text=True,timeout=10)
            if status.returncode or status.stdout.strip() in {'active','activating','deactivating','reloading'}:
                raise RuntimeError('A pipeline is running; no files changed')
        plans=prepare(root,systemd)
        # Install this tested entry point as well, without a recursive manifest.
        target=root/'automation/server/install_recovery.py'
        raw=Path(__file__).read_bytes()
        if target.is_symlink():raise RuntimeError('Unexpected installer symlink')
        before=target.read_bytes() if target.exists() else None
        if before is not None and before!=raw:raise RuntimeError('Unknown installed installer version; no files changed')
        plans.append((target,raw,before,target.stat() if target.exists() else None))
        backup=store/'repairs'/('self-recovery-'+str(time.time_ns()))
        if backup.parent.is_symlink():raise RuntimeError('Unexpected backup directory')
        backup.mkdir(parents=True,mode=0o700)
        metadata=[]
        for index,(target,raw,before,stat) in enumerate(plans):
            if before is not None:
                saved=backup/str(index);saved.write_bytes(before);saved.chmod(0o600)
            metadata.append(dict(path=str(target),existed=before is not None,
                                 uid=stat.st_uid if stat else 0,gid=stat.st_gid if stat else 0,
                                 mode=(stat.st_mode&0o7777) if stat else 0o644))
        import json
        (backup/'metadata.json').write_text(json.dumps(metadata,indent=2))
        applied=[]
        timer_was_active=subprocess.run(['systemctl','is-active','--quiet','fh6-recovery.timer']).returncode==0
        try:
            for target,raw,before,stat in plans:
                replace(target,raw,stat.st_uid if stat else 0,stat.st_gid if stat else 0,
                        (stat.st_mode&0o7777) if stat else 0o644)
                applied.append((target,before,stat))
            subprocess.run(['systemd-analyze','verify',str(systemd/'fh6-recovery.service'),
                str(systemd/'fh6-recovery-run.service'),str(systemd/'fh6-recovery.timer')],check=True,timeout=30)
            for test in ['automation/server/test_recovery.py','automation/server/test_diagnose.py',
                         'automation/server/test_install_recovery.py','automation/server/test_server.py',
                         'automation/test_refresh_guard.py','automation/test_portable_report.py']:
                subprocess.run(['python3',str(root/test)],cwd=root,check=True,timeout=300)
            subprocess.run(['systemctl','daemon-reload'],check=True,timeout=30)
            subprocess.run(['systemctl','enable','--now','fh6-recovery.timer'],check=True,timeout=30)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-recovery.timer','fh6-phone.service'],check=True,timeout=30)
        except BaseException:
            if not timer_was_active:
                subprocess.run(['systemctl','disable','--now','fh6-recovery.timer'],timeout=30)
            for target,before,stat in reversed(applied):
                if before is None:target.unlink(missing_ok=True)
                else:replace(target,before,stat.st_uid,stat.st_gid,stat.st_mode&0o7777)
            subprocess.run(['systemctl','daemon-reload'],timeout=30)
            subprocess.run(['systemctl','restart','fh6-phone.service'],timeout=30)
            raise
        print('FH6_SELF_RECOVERY_INSTALLED timer=active tests=passed; no live pipeline invoked')
        print('BACKUP='+str(backup))

if __name__=='__main__':
    main()
